#!/usr/bin/env node
/**
 * Apply this repository's Attio template to the client's own Attio workspace.
 *
 *   ATTIO_API_KEY=... node apply-attio-template.mjs [path/to/attio-template.json]
 *
 * Requires an Attio API key with full data + configuration scopes, generated by the
 * CLIENT in their own workspace (Settings → Developers → API keys — see
 * crm/attio/README.md for a first-time, click-by-click walkthrough if they've never done
 * this before). The key is only ever used for this one command; delete it from anywhere
 * it was pasted once the install is validated (the n8n workflows use their own separate
 * credential — see connectors/connector-checklist.md).
 *
 * Idempotent: re-running skips anything that already exists (matched by api_slug), so a
 * partial failure — including "I closed my laptop halfway through" — is safe to retry.
 *
 * Views cannot be created via the Attio public API — set them up in the UI per README.md.
 */

import { readFileSync } from 'node:fs';

const API = 'https://api.attio.com/v2';
const KEY = process.env.ATTIO_API_KEY;
if (!KEY) {
  console.error('ATTIO_API_KEY is not set. Generate one in your Attio workspace (see crm/attio/README.md) and re-run.');
  process.exit(1);
}

const templatePath = process.argv[2] ?? new URL('./attio-template.json', import.meta.url);
const template = JSON.parse(readFileSync(templatePath, 'utf8'));

async function attio(method, path, body) {
  const res = await fetch(`${API}${path}`, {
    method,
    headers: { Authorization: `Bearer ${KEY}`, 'Content-Type': 'application/json' },
    body: body ? JSON.stringify(body) : undefined,
  });
  const json = await res.json().catch(() => ({}));
  if (!res.ok) {
    const err = new Error(`${method} ${path} → ${res.status}: ${JSON.stringify(json)}`);
    err.status = res.status;
    throw err;
  }
  return json;
}

/** Create-if-missing helper: treat slug conflicts as "already applied". */
async function ensure(label, fn) {
  try {
    const result = await fn();
    console.log(`  ✓ created ${label}`);
    return result;
  } catch (err) {
    // 409 = slug conflict; Attio also returns 400 with a uniqueness message on some routes.
    if (err.status === 409 || /already exists|not unique|conflict/i.test(err.message)) {
      console.log(`  • ${label} already exists — skipped`);
      return null;
    }
    throw err;
  }
}

function attributePayload(attr) {
  const type = attr.type === 'checkbox' ? 'checkbox' : attr.type;
  return {
    data: {
      title: attr.title,
      api_slug: attr.api_slug,
      type,
      is_required: false,
      is_unique: false,
      is_multiselect: attr.is_multiselect ?? false,
      config: {},
    },
  };
}

async function createList(listSpec, parentObject) {
  await ensure(`list "${listSpec.name}"`, () =>
    attio('POST', '/lists', {
      data: {
        name: listSpec.name,
        api_slug: listSpec.api_slug,
        parent_object: parentObject,
        workspace_access: 'full-access',
        workspace_member_access: [],
      },
    }),
  );

  if (listSpec.stage_attribute) {
    const stage = listSpec.stage_attribute;
    await ensure(`status attribute "${stage.title}" on ${listSpec.api_slug}`, () =>
      attio('POST', `/lists/${listSpec.api_slug}/attributes`, {
        data: {
          title: stage.title,
          api_slug: stage.api_slug,
          type: 'status',
          is_required: false,
          is_unique: false,
          is_multiselect: false,
          config: {},
        },
      }),
    );
    for (const status of stage.statuses) {
      await ensure(`stage "${status.title}"`, () =>
        attio('POST', `/lists/${listSpec.api_slug}/attributes/${stage.api_slug}/statuses`, {
          data: { title: status.title, celebration_enabled: status.celebration ?? false },
        }),
      );
    }
  }

  for (const attr of listSpec.entry_attributes ?? []) {
    await ensure(`attribute "${attr.title}" on ${listSpec.api_slug}`, () =>
      attio('POST', `/lists/${listSpec.api_slug}/attributes`, attributePayload(attr)),
    );
    if (attr.type === 'select' && attr.options) {
      for (const option of attr.options) {
        await ensure(`option "${option}" on ${attr.api_slug}`, () =>
          attio('POST', `/lists/${listSpec.api_slug}/attributes/${attr.api_slug}/options`, {
            data: { title: option },
          }),
        );
      }
    }
  }
}

console.log(`Applying Attio template (v${template.kit_version}) — parent object: ${template.parent_object}`);

console.log('\nSales pipeline:');
await createList(template.pipeline_list, template.parent_object);

console.log('\nHarness install record:');
await createList(template.harness_install_list, template.parent_object);

console.log(`\nDone. Now create the ${template.views_manual_setup.views.length} views in the Attio UI (see README.md) —`);
for (const view of template.views_manual_setup.views) {
  console.log(`  → ${view.name} (${view.type}): ${view.filter ?? `group by ${view.group_by}`}`);
}
console.log('\nThen fill the single Harness Install entry with your own profile + template version.');
